-- Add visible pattern families to the hub and six field approaches in Studio Edit.
assert(game.PlaceId == 124078027733625 and game.GameId == 10774898335, "Wrong shared place")
assert(not game:GetService("RunService"):IsRunning(), "Stop Play before editing")
local root = workspace.MiningAway
local map, mat = root.Map, game:GetService("MaterialService")
local current = map.QuarryContinuousGround
local v, rgb = Vector3.new, Color3.fromRGB
assert(not map:FindFirstChild("QuarryMotifScenery") and not shared.QuarryMotifs)

-- The tiles are generated by tools/draw_quarry_motifs.py and uploaded as images.
local definitions = {
    Stars = {"130509631570789", 5.6},
    Daisies = {"87001180278589", 5.3},
    BlueGingham = {"83914366857318", 7.0},
    RedGingham = {"111854869033768", 7.0},
    Pips = {"140704715063691", 4.7},
    Waves = {"109395106577220", 5.8},
    Knit = {"126905018997201", 5.6},
    Studs = {"107794782432490", 4.8},
}
local material, pending, decals = {}, {}, {}
for key, data in pairs(definitions) do
    local variant = Instance.new("MaterialVariant")
    variant.Name = "QuarryMotif_" .. key
    assert(not mat:FindFirstChild(variant.Name), variant.Name .. " already exists")
    variant.BaseMaterial = Enum.Material.Slate
    variant.ColorMap = "rbxassetid://" .. data[1]
    variant.RoughnessMap = "rbxassetid://78519593640803"
    variant.StudsPerTile = data[2]
    variant.MaterialPattern = Enum.MaterialPattern.Regular
    material[key] = variant
    table.insert(pending, variant)
    local image = Instance.new("Decal")
    image.Texture = variant.ColorMap
    table.insert(decals, image)
end
local loaded = {}
game:GetService("ContentProvider"):PreloadAsync(decals, function(id, status)
    loaded[id] = status == Enum.AssetFetchStatus.Success
end)
for _, image in ipairs(decals) do
    local ok, id = loaded[image.Texture], image.Texture
    image:Destroy()
    assert(ok, "Texture unavailable in Studio: " .. id)
end

material.Brick = mat.QuarryAccent_Brick
material.Timber = mat.QuarryAccent_Timber
material.Rose = mat.QuarryPhoto_Slate
material.Checker = mat.QuarryAccent_Checker

local function folder(name, parent)
    local instance = Instance.new("Folder")
    instance.Name, instance.Parent = name, parent
    return instance
end
local scenery = folder("QuarryMotifScenery")

local protected, occupied = {}, {}
local function rect(frame, size, margin)
    local h, r, u, f = size/2, frame.RightVector, frame.UpVector, frame.LookVector
    return {frame.X, frame.Z,
        math.abs(r.X)*h.X+math.abs(u.X)*h.Y+math.abs(f.X)*h.Z+margin,
        math.abs(r.Z)*h.X+math.abs(u.Z)*h.Y+math.abs(f.Z)*h.Z+margin}
end
local function mark(list, part, margin)
    table.insert(list, rect(part.CFrame, part.Size, margin))
end
for _, field in ipairs(root.Fields:GetChildren()) do mark(protected, field.Field, .8) end
for _, route in ipairs(map.DronerevolutionTerraces.WalkableRoutes:GetChildren()) do mark(protected, route, 1) end
for _, part in ipairs(map.EmeraldChalkLagoon:GetChildren()) do
    if part.Name == "LagoonCauseway" then mark(protected, part, .8) end
end
for _, item in ipairs(map:GetDescendants()) do
    if item:IsA("ProximityPrompt") and item.Parent:IsA("BasePart") then mark(protected, item.Parent, 4.5) end
end
for _, part in ipairs(map.SimpleFlatTestMap:GetDescendants()) do
    if part:IsA("BasePart") and part.Name:match("Pad$") and part.Name ~= "HubPad" then mark(protected, part, 1.4) end
end
-- The player start and its main line through the hub stay clear.
table.insert(protected, {0,10,7,23})

for _, part in ipairs(current.PatternedAccents:GetChildren()) do mark(occupied, part, 1.5) end
for _, part in ipairs(map.QuarryArrivalAccents:GetDescendants()) do
    if part:IsA("BasePart") then mark(occupied, part, .9) end
end
for _, model in ipairs(current.OriginalDetails:GetDescendants()) do
    if model:IsA("Model") then
        local frame, size = model:GetBoundingBox()
        local entry = rect(frame, size, .8)
        -- A mushroom cap can overhang the ground where a small sample sits.
        if model.Name == "Blue Trumpet" or model.Name == "Coral Fan" then
            entry[3], entry[4] = entry[3]*.40, entry[4]*.40
        end
        table.insert(occupied, entry)
    end
end
for _, item in ipairs(map.DronerevolutionTerraces.AssetScenery:GetDescendants()) do
    if item:IsA("Model") and item.Name:match("^%d%d_") then
        local frame, size = item:GetBoundingBox()
        table.insert(occupied, rect(frame, size, .8))
    end
end

local params = RaycastParams.new()
params.RespectCanCollide = true
local function overlaps(list, x, z, radius)
    for _, r in ipairs(list) do
        if math.abs(x-r[1]) < radius+r[3] and math.abs(z-r[2]) < radius+r[4] then return true end
    end
    return false
end

local function ground(x, z, expected, radius)
    if overlaps(protected,x,z,radius) or overlaps(occupied,x,z,radius) then return nil end
    local level
    for _, d in ipairs({v(0,0,0),v(radius,0,radius),v(-radius,0,radius),
        v(radius,0,-radius),v(-radius,0,-radius)}) do
        local hit = workspace:Raycast(v(x,expected+1,z)+d,v(0,-1.3,0),params)
        if not hit or hit.Normal.Y < .98 or math.abs(hit.Position.Y-expected) > .14
            or (level and math.abs(hit.Position.Y-level) > .08) then return nil end
        level = level or hit.Position.Y
    end
    return level
end

local white, rose = rgb(255,255,255), rgb(230,145,165)
local tallies, usage, missed = {}, {}, {}
local random = Random.new(86153)
local offsets = {{0,0},{2,0},{-2,0},{0,2},{0,-2},{3,3},{-3,3},{3,-3},{-3,-3}}
local function decorate(region, level, placements)
    local group = folder(region, scenery)
    for _, entry in ipairs(placements) do
        local key, x, z, width, form = table.unpack(entry)
        local isPaver = form == "Paver"
        local yaw = isPaver and 0 or random:NextNumber(-.27,.27)
        local radius = width*(math.abs(math.cos(yaw))+math.abs(math.sin(yaw)))/2
        local height = isPaver and .05 or form == "Low" and width*.38 or width
        local placed = false
        for _, offset in ipairs(offsets) do
            local px, pz = x+offset[1], z+offset[2]
            local at = ground(px,pz,level,radius)
            if at then
                local part = Instance.new("Part")
                local finish = material[key]
                part.Name = key .. form
                part.Size = v(width,height,width)
                part.CFrame = CFrame.new(px,at+height/2,pz)*CFrame.Angles(0,yaw,0)
                part.Material, part.MaterialVariant = finish.BaseMaterial, finish.Name
                part.Color = key == "Rose" and rose or white
                part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch = true,false,false,false
                part.TopSurface, part.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth
                part.CastShadow = not isPaver
                part.Parent = group
                table.insert(occupied,{px,pz,radius+1.5,radius+1.5})
                usage[key] = (usage[key] or 0)+1
                placed = true
                break
            end
        end
        if not placed then table.insert(missed, {region,key,x,z}) end
    end
    tallies[region] = #group:GetChildren()
    assert(tallies[region]>=7, "Too few visible accents in " .. region)
end

