for key in pairs(definitions) do assert((usage[key] or 0)>=3, "Too few uses of " .. key) end

local serialize, enc = game:GetService("SerializationService"), game:GetService("EncodingService")
local function encode(items)
    local bytes = serialize:SerializeInstancesAsync(items)
    return buffer.tostring(enc:Base64Encode(enc:CompressBuffer(bytes,Enum.CompressionAlgorithm.Zstd)))
end
local snapshot = {scenery=encode({scenery}),variants=encode(pending)}
local function apply()
    assert(not scenery.Parent and not map:FindFirstChild(scenery.Name))
    for _, variant in ipairs(pending) do assert(not mat:FindFirstChild(variant.Name)) end
    for _, variant in ipairs(pending) do variant.Parent = mat end
    scenery.Parent = map
    return {regions=tallies,usage=usage}
end
shared.QuarryMotifs = {snapshot=snapshot,apply=apply}
return {regions=tallies,usage=usage,skipped=missed,sceneryBytes=#snapshot.scenery,variantBytes=#snapshot.variants}
